/**
 * Shared chart utilities for Medical Incident Report tabs
 */

import { MedicalIncidentReportFilters } from '../../models/MedicalIncident';
import { scykRoutes } from '../../config/scykRoutes';

// ── List navigation URL builders ──────────────────────────────────────────────

function baseListParams(f: MedicalIncidentReportFilters): URLSearchParams {
  const p = new URLSearchParams();
  if (f.dateFrom)     p.set('dateFrom',     f.dateFrom);
  if (f.dateTo)       p.set('dateTo',       f.dateTo);
  if (f.reportingDepartmentId) p.set('reportingDepartmentId', f.reportingDepartmentId);
  return p;
}

/** Navigate to list filtered to a specific calendar month from the active report period. */
export function buildMonthListUrl(monthKey: string, f: MedicalIncidentReportFilters): string {
  const m = parseInt(monthKey, 10);
  if (isNaN(m) || m < 1 || m > 12) return scykRoutes.incidents.list;
  const year     = f.dateFrom ? new Date(`${f.dateFrom}T00:00:00`).getFullYear() : new Date().getFullYear();
  const dateFrom = `${year}-${String(m).padStart(2, '0')}-01`;
  const dateTo   = `${year}-${String(m).padStart(2, '0')}-${new Date(year, m, 0).getDate()}`;
  const p = new URLSearchParams({ dateFrom, dateTo });
  if (f.reportingDepartmentId) p.set('reportingDepartmentId', f.reportingDepartmentId);
  return `${scykRoutes.incidents.list}?${p}`;
}

/** Navigate to list filtered by severity. */
export function buildSeverityListUrl(key: string, f: MedicalIncidentReportFilters): string {
  const p = baseListParams(f);
  p.set('severity', key);
  return `${scykRoutes.incidents.list}?${p}`;
}

/** Navigate to list filtered by reportType. */
export function buildReportTypeListUrl(key: string, f: MedicalIncidentReportFilters): string {
  const p = baseListParams(f);
  p.set('reportType', key);
  return `${scykRoutes.incidents.list}?${p}`;
}

/** Navigate to list with only the report's base date/dept filter (no extra dimension). */
export function buildBaseDateListUrl(f: MedicalIncidentReportFilters): string {
  const p = baseListParams(f);
  const qs = p.toString();
  return `${scykRoutes.incidents.list}${qs ? `?${qs}` : ''}`;
}

