import { MEDICAL_INCIDENT_PERMISSIONS as P } from '../constants/medicalIncidentPermissionCodes';
import { hasFullIncidentListAccess, hasPermissionCode } from '../utils/medicalPermissionCode';

export { hasPermissionCode };

/**
 * Granular Auth permission gates — medical incident list + form (SCYK).
 * SSOT: Linm.Authentication/data/navigation/sets/medical-incidents/
 */
export function useMedicalIncidentPermissions() {
  const canRead             = hasPermissionCode(P.read);
  const canCreate           = hasPermissionCode(P.create);
  const canSaveDraft        = hasPermissionCode(P.saveDraft);
  const canSubmitReport     = hasPermissionCode(P.submit);
  const canDelete           = hasPermissionCode(P.delete);
  const canStartAnalysis    = hasPermissionCode(P.startAnalysis);
  const canSaveAnalysis     = hasPermissionCode(P.saveAnalysis);
  const canCompleteAnalysis = hasPermissionCode(P.completeAnalysis);
  const canEditWhenComplete = hasPermissionCode(P.editWhenComplete);
  const canToggleMismatch   = hasPermissionCode(P.toggleMismatch);
  const canToggleNotMedical = hasPermissionCode(P.toggleNotMedical);
  const canExport           = hasPermissionCode(P.export);
  const canImport           = hasPermissionCode(P.import);
  const canBatchStatus      = hasPermissionCode(P.batchStatus);

  /** Reporter-only scope (list filtered to own records on BE). */
  const isReporterScope =
    canRead
    && !hasFullIncidentListAccess({
      canStartAnalysis,
      canSaveAnalysis,
      canCompleteAnalysis,
      canEditWhenComplete,
      canBatchStatus,
      canImport,
    });

  return {
    canRead,
    canCreate,
    canSaveDraft,
    canSubmitReport,
    canDelete,
    canStartAnalysis,
    canSaveAnalysis,
    canCompleteAnalysis,
    canEditWhenComplete,
    canToggleMismatch,
    canToggleNotMedical,
    canExport,
    canImport,
    canBatchStatus,
    canPrint: canRead,
    isReporterScope,
  };
};
